## **`fechar-caixa.js` Logic**

```javascript
// Load and display today's sales
function carregarVendasHoje() {
  fetch("http://localhost:3000/vendas")
    .then(res => res.json())
    .then(vendas => {
      const hoje = new Date();
      const vendasHoje = vendas.filter(venda =>
        new Date(venda.data).toDateString() === hoje.toDateString()
      );

      renderVendas(vendasHoje);
      atualizarTotalCaixa(vendasHoje);
    })
    .catch(err => {
      console.error(err);
      alert("Erro ao carregar vendas");
    });
}

// Render sales list
function renderVendas(vendas) {
  const lista = document.getElementById("lista-vendas-caixa");
  lista.innerHTML = "";

  if (vendas.length === 0) {
    lista.innerHTML = `<p style="text-align: center; color: #6b7280;">Nenhuma venda registrada para hoje</p>`;
    return;
  }

  vendas.forEach(venda => {
    const dataFormatada = new Date(venda.data).toLocaleTimeString("pt-BR", {
      hour: "2-digit",
      minute: "2-digit"
    });

    const vendaItem = document.createElement("div");
    vendaItem.className = "venda-item";
    vendaItem.innerHTML = `
      <div class="venda-info">
        <span class="venda-data">${dataFormatada}</span>
        <span class="venda-data">${venda.itens.length} item(ns)</span>
      </div>
      <span class="venda-total">R$ ${venda.total.toFixed(2)}</span>
    `;

    lista.appendChild(vendaItem);
  });
}

// Update total box
function atualizarTotalCaixa(vendas) {
  const total = vendas.reduce((sum, venda) => sum + venda.total, 0);
  document.getElementById("total-caixa").innerText = `R$ ${total.toFixed(2)}`;
}

// Go back to main page
function voltarPagina() {
  window.location.href = "/src/html/pagina-inicial.html";
}

// Confirm cash-out and save to caixas
function confirmarFechamento() {
  fetch("http://localhost:3000/vendas")
    .then(res => res.json())
    .then(vendas => {
      const hoje = new Date();
      const vendasHoje = vendas.filter(venda =>
        new Date(venda.data).toDateString() === hoje.toDateString()
      );

      if (vendasHoje.length === 0) {
        alert("Nenhuma venda registrada para hoje");
        return;
      }

      const totalHoje = vendasHoje.reduce((sum, venda) => sum + venda.total, 0);
      const vendaIds = vendasHoje.map(venda => venda.id);

      const confirmou = confirm(
        `Confirmar fechamento de caixa com total R$ ${totalHoje.toFixed(2)}?`
      );

      if (!confirmou) return;

      return fetch("http://localhost:3000/caixas", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          data: hoje.toISOString(),
          dia: hoje.getDate(),
          mes: hoje.getMonth() + 1,
          ano: hoje.getFullYear(),
          total: totalHoje,
          venda_ids: vendaIds
        })
      });
    })
    .then(res => {
      if (!res.ok) throw new Error("Erro ao salvar fechamento");
      alert("Caixa fechado com sucesso!");
      window.location.href = "/src/html/pagina-inicial.html";
    })
    .catch(err => {
      console.error(err);
      alert("Erro ao confirmar fechamento");
    });
}

// Initialize on page load
window.onload = function() {
  carregarVendasHoje();
};
```

---

## **What this does**

- **`carregarVendasHoje()`**: Fetches all sales from `/vendas`, filters by today's date, then renders them and updates the total
- **`renderVendas()`**: Loops through sales and displays each one with time and item count; shows "no sales" message if empty
- **`atualizarTotalCaixa()`**: Calculates and displays the sum of all today's sales
- **`voltarPagina()`**: Redirects back to the main page
- **`confirmarFechamento()`**: Shows confirmation dialog, then creates a new `caixa` record with today's total and all venda IDs; redirects to main page on success
- **`window.onload`**: Runs on page load to populate the sales list

---

## **Data flow**

1. Page loads → calls `carregarVendasHoje()`
2. Fetches vendas, filters by today, renders list, shows total
3. User clicks "Confirmar Fechamento" → `confirmarFechamento()` runs
4. Confirmation dialog appears
5. If confirmed → POSTs new `caixa` record with `venda_ids` array
6. Redirects back to main page

