Updating the `renderVendas()` function to aggregate and display item counts by product name.

```javascript
function renderVendas(vendas) {
  const lista = document.getElementById("lista-vendas-caixa");
  lista.innerHTML = "";

  if (vendas.length === 0) {
    lista.innerHTML = `<p style="text-align: center; color: #6b7280;">Nenhuma venda registrada para hoje</p>`;
    return;
  }

  // Aggregate items from all sales
  const itemsAgregados = {};
  vendas.forEach(venda => {
    venda.itens.forEach(item => {
      if (itemsAgregados[item.nome_produto]) {
        itemsAgregados[item.nome_produto] += item.quantidade;
      } else {
        itemsAgregados[item.nome_produto] = item.quantidade;
      }
    });
  });

  // Render aggregated items
  Object.entries(itemsAgregados).forEach(([nome, quantidade]) => {
    const itemElement = document.createElement("div");
    itemElement.className = "venda-item";
    itemElement.innerHTML = `
      <span class="venda-data">x${quantidade} ${nome}</span>
    `;
    lista.appendChild(itemElement);
  });
}
```

